def visual_content(c):
    out=''
    if c.get('images'):
        out+='<section class="visual-block"><h3>실제 Final Cut Pro 화면으로 확인</h3><p class="visual-note">Apple 공식 가이드에서 가져온 실제 화면입니다. 이미지를 누르면 크게 볼 수 있습니다. 앱 버전·언어에 따라 표시가 다를 수 있습니다.</p><div class="ui-grid">'
        for im in c['images']:
            out+=f'<figure class="ui-image"><a href="{E(im["path"])}" target="_blank" rel="noopener"><img loading="lazy" src="{E(im["path"])}" alt="{E(im["alt"])}"></a><figcaption>{E(im["caption"])}<small>{E(im["credit"])} · <a href="{E(im["source"])}" target="_blank" rel="noopener">원문 ↗</a></small></figcaption></figure>'
        out+='</div></section>'
    for t in c.get('tables',[]):
        out+=f'<h3>{E(t["title"])}</h3><div class="table-scroll"><table><thead><tr>'+''.join('<th scope="col">'+E(x)+'</th>' for x in t['heads'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(x)+'</td>' for x in row)+'</tr>' for row in t['rows'])+'</tbody></table></div>'
    if c.get('photo'):
        k=c['photo']['kind'];cards={
          'market':[('market',0,'A · 기둥이 등장'),('market',2,'A · 전경이 지나감'),('market',5,'B · 해변으로 도착')],
          'wipe':[('market',2,'A · 위 레이어 / 기둥 경계'),('market',3,'B · 아래 레이어 / 다음 장소')],
          'match':[('match',0,'A · 중앙의 커피 원형'),('match',1,'B · 중앙의 수영장 원형')],
          'motion':[('match',2,'t₀ · 이전 인물 위치'),('match',3,'t₁ · 다음 인물 위치')],
          'water':[('match',4,'수중 · 고역 감소 구간'),('match',5,'수면 위 · 고역 복귀 구간')],
          'film':[('match',0,'디테일'),('market',1,'해변'),('market',0,'시장')],
          'split':[('market',0,'인물'),('market',1,'장소'),('match',0,'디테일')]}[k]
        out+='<section class="visual-block"><h3>사진으로 보는 배치와 연결</h3><div class="photo-grid '+E(k)+'">'
        for atlas,n,label in cards:
            pos=[('0%','0%'),('100%','0%'),('0%','50%'),('100%','50%'),('0%','100%'),('100%','100%')][n]
            file='market-beach' if atlas=='market' else 'match-motion-water'
            out+=f'<figure><div class="photo-cell" role="img" aria-label="{E(label)}" style="background-image:url(assets/examples/{file}.webp);background-position:{pos[0]} {pos[1]}"></div><figcaption>{E(label)}</figcaption></figure>'
        out+='</div>'
        if k=='wipe':
            out+='<div class="layer-stack"><div><b>위 · A 시장</b><span>Draw Mask → 전경 경계의 위치 키프레임</span></div><div><b>아래 · B 해변</b><span>A와 겹쳐 놓기 → A가 사라진 부분에 B 노출</span></div><div><b>음악·현장음</b><span>전환과 별개로 유지 · 필요하면 파도 J-cut</span></div></div><p>전경 윤곽에 맞춰 A의 보이는 영역을 줄입니다. Feather는 윤곽 위치를 맞춘 뒤 조절합니다. 이 사진은 구조 설명용이며 실제 마스크 추적 결과가 아닙니다.</p>'
        if k=='motion':out+='<p>위: t₀ 프레임에서 분리한 인물 Freeze Frame · 아래: t₁의 움직이는 원본. 인물만 남기는 마스크와 불투명도 키프레임을 사용합니다. 사진 두 장은 위치 관계를 설명하며 실제 앱 출력이 아닙니다.</p>'
        if k=='split':out+='<p>FCP 레이어: 인물 / 장소 / 디테일 클립을 같은 시간에 연결하고 각각 Crop·Transform으로 패널 위치를 지정합니다. 아래 배경은 검정이나 여백입니다.</p>'
        out+=f'<p class="visual-note">{E(c["photo"]["caption"])}. 생성한 연습용 사진이며 특정 크리에이터의 원본 장면·FCP 화면이 아닙니다.</p></section>'
    for panel in c.get('frame_panels',[]):
        out+=f'<section class="visual-block"><h3>{E(panel["title"])}</h3><div class="frame-grid">'+''.join(f'<figure><img loading="lazy" src="{E(im["path"])}" alt="{E(im["label"])}"><figcaption>{E(im["label"])}</figcaption></figure>' for im in panel['frames'])+f'</div><p class="visual-note">{E(panel["credit"])}</p></section>'
    return out

def article(c,i):
    steps=''.join('<li>'+E(s)+'</li>' for s in c['steps'])
    fig=f'<figure class="figure" data-figure="{E(c["figure"])}"><div class="drawing"></div><figcaption>직접 만든 원리 설명용 도식입니다. 실제 앱 화면이나 효과 출력의 복제본이 아닙니다.</figcaption></figure>' if c['figure'] else ''
    refs=''.join(f'<a href="{E(url)}" target="_blank" rel="noopener">{E(label)} ↗</a> ' for label,url in c.get('references',[]))
    rel=chapters[max(0,i-1):min(len(chapters),i+2)]
    related=''.join(f'<a href="#{r["id"]}">{E(r["title"])}</a>' for r in rel if r['id']!=c['id'])
    return f'''<article class="entry hidden" id="{c['id']}" data-part="{c['part']}"><div class="entry-top"><span class="eyebrow">PART {c['part']+1} · {i+1:02d} / {len(chapters)}</span><label class="read"><input type="checkbox" data-read="{c['id']}"> 읽음 표시</label></div><h2>{E(c['title'])}</h2><p class="intro">{E(c['intro'])}</p><h3>왜 이 방법을 쓰는가</h3><p>{E(c['why'])}</p>{fig}{visual_content(c)}<h3>실제 작업 순서</h3><ol class="steps">{steps}</ol><h3>장면으로 이해하기</h3><p>{E(c['case'])}</p><div class="note warning"><strong>막히거나 과해질 때</strong><p>{E(c['trap'])}</p></div><div class="practice"><strong>직접 해볼 실습 · 완료 기준</strong><p>{E(c['practice'])}</p></div><div class="related">{related}</div><div class="source">{refs}<p>기능의 메뉴·조건은 <a href="{E(c['source'])}" target="_blank" rel="noopener">원문 안내</a>에서 설치 버전으로 확인하세요. 장면 예시·수치·실습·작업 방식의 선택은 이 교재의 제안입니다.</p></div></article>'''
